package com.doctoolkit.controller;
import com.doctoolkit.service.FileConversionService; import org.springframework.core.io.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.nio.file.*; import java.util.*;
@RestController public class DocumentController { private final FileConversionService svc; public DocumentController(FileConversionService svc){this.svc=svc;} @PostMapping("/convert") ResponseEntity<Resource> convert(@RequestPart MultipartFile file,@RequestParam String targetFormat)throws Exception{return respond(svc.convert(file,targetFormat));} @PostMapping("/compress") ResponseEntity<Resource> compress(@RequestPart MultipartFile file)throws Exception{return respond(svc.compress(file));} @PostMapping("/merge") ResponseEntity<Resource> merge(@RequestPart List<MultipartFile> files)throws Exception{return respond(svc.merge(files));} @PostMapping("/split") ResponseEntity<Resource> split(@RequestPart MultipartFile file,@RequestParam String ranges)throws Exception{return respond(svc.split(file,ranges));} @PostMapping("/ocr") ResponseEntity<Resource> ocr(@RequestPart MultipartFile file,@RequestParam(required=false) String languages)throws Exception{return respond(svc.ocr(file,languages));} private ResponseEntity<Resource> respond(Path p){return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+p.getFileName()+"\"").contentLength(p.toFile().length()).contentType(MediaType.APPLICATION_OCTET_STREAM).body(new FileSystemResource(p));} }
